# Check mapping for small mods
import numpy as np

demo_output = """5 5 1 3 1 9 6 5 5 1 3 1 9 6 5 5 1 3 1
5 1 3 1 9 6 5 5 1 3 1 9 6 5 5 1 3 1 9
1 3 1 9 6 5 5 1 3 1 9 6 5 5 1 3 1 9 6
3 1 9 6 5 5 1 3 1 9 6 5 5 1 3 1 9 6 5
1 9 6 5 5 1 3 1 9 6 5 5 1 3 1 9 6 5 5"""

out_grid = np.array([list(map(int, line.split())) for line in demo_output.strip().split('\n')])

for mod in range(2, 7):
    mapping = {}
    consistent = True
    for r in range(5):
        for c in range(5):
            s = (r + c) % mod
            val = out_grid[r,c]
            if s not in mapping:
                mapping[s] = val
            elif mapping[s] != val:
                print(f"Mod {mod}: Mismatch at ({r},{c}), sum={s}, expected={mapping[s]}, got={val}")
                consistent = False

    if consistent:
        print(f"Mod {mod} CONSISTENT: mapping = {mapping}")

# Also check just row by column
print("\n--- By column only ---")
for col in range(10):
