# Find actual periodicity by looking for where sequences restart
import numpy as np

demo_output = """5 5 1 3 1 9 6 5 5 1 3 1 9 6 5 5 1 3 1"""
out_grid = np.array([list(map(int, line.split())) for line in demo_output.strip().split('\n')])

row0 = out_grid[0]
print(f"Row 0: {row0}")

# Look for where row starts repeating
for start in range(7):
    for end in range(start+5, min(len(row0)+1, start+15)):
        seq = tuple(row0[start:end])
        # Check if this sequence continues
        matches = True
        for i in range(start, end):
            if i + len(seq) <= len(row0):
                if row0[i+len(seq)] != seq[0]:
                    matches = False
                    break
        if matches:
            print(f"Starting at index {start}, sequence of length {end-start}: {seq}")
            break

# Now let's try to understand: maybe each position (r,c) has value based on some formula involving both r and c
# with a different period

# Let me try period 10
print("\n\nTesting period 10...")
for pr in [6, 8, 9, 10, 12, 14, 15]:
    consistent = True
    seen = {}
    for r in range(19):
        for c in range(19):
            idx = (r % pr, c % pr)
            val = out_grid[r,c]
            if idx not in seen:
                seen[idx] = val
            elif seen[idx] != val:
                consistent = False
                # print(f"Period {pr} fails at ({r},{c})")
                break
        if not consistent:
            break
    if consistent:
        print(f"Period {pr} works!")

